// Serves the Helpr wordmark to email clients.
//
// WHY THIS EXISTS: every transactional email pointed its <img> at
// THE ASSET IS THE H MARK, NOT THE WORDMARK (owner, 2026-08-27: "this should
// just be h logo no word mark"). The constant name is kept so every caller
// keeps working; only the bytes changed. Source: public/helpr-splash-icon.png
// at 160px wide, transparent, displayed at 80px so it stays crisp on retina
// mail clients.
//
// https://www.louisianahelpr.com/helpr-wordmark.png, and that host sits behind
// Vercel's security checkpoint. A browser solves the JS challenge; an email
// client cannot. Gmail's and Apple Mail's image proxies both received a 429
// challenge page instead of the PNG, so the single brand element in every
// signup, reset, approval and notification email rendered as a broken image.
// Verified from two separate networks, so it was not local rate-limiting.
//
// Email images must not depend on the marketing site's bot-protection posture,
// which can be toggled at any time by someone who is not thinking about email.
// Serving the bytes from the API origin — which email proxies reach normally —
// removes that coupling entirely.
//
// The PNG is inlined as base64 rather than fetched from Storage so this has no
// runtime dependency, no bucket policy to keep public, and no second failure
// mode. It is ~7 KB; the decode happens once per cold start.
//
// verify_jwt is false in config.toml BY NECESSITY: an email client sends no
// Authorization header. Nothing here reads user data — it returns one static
// public logo, the same bytes the marketing site serves anonymously.

const WORDMARK_BASE64 = "";

const BYTES = Uint8Array.from(atob(WORDMARK_BASE64), (c) => c.charCodeAt(0));

Deno.serve((req: Request) => {
  if (req.method !== "GET" && req.method !== "HEAD") {
    return new Response("Method not allowed", { status: 405 });
  }

  return new Response(req.method === "HEAD" ? null : BYTES, {
    status: 200,
    headers: {
      "Content-Type": "image/png",
      "Content-Length": String(BYTES.byteLength),
      // Immutable: the bytes are baked into this deployment, so a change ships
      // as a new deploy rather than a mutation of this URL. Long max-age keeps
      // Gmail's proxy from re-fetching on every open.
      "Cache-Control": "public, max-age=31536000, immutable",
      "Access-Control-Allow-Origin": "*",
    },
  });
});
